begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('e1000000-0000-4000-8000-000000000001'),('e1000000-0000-4000-8000-000000000002');
insert into profiles(id,display_name,consented_at,timezone) select id,'Push fixture',now(),'UTC' from auth.users where id::text like 'e1000000-%';
insert into families(id,name) values('e2000000-0000-4000-8000-000000000001','Push fixture');
insert into family_members(family_id,user_id,role) values('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','owner');
insert into children(id,family_id,name,sex,birth_date) values('e3000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Push baby','female',current_date);
delete from feeding_push_config;
insert into feeding_push_config(public_key,worker_url,token_secret_id) values(repeat('B',87),'https://example.invalid',(select vault.create_secret(repeat('a',64),'push-test-'||gen_random_uuid())));
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(get_feeding_push_config(),repeat('B',87),'authenticated clients receive public VAPID key only');
select lives_ok($$select enable_feeding_push(jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/test-owner','keys',jsonb_build_object('p256dh',repeat('B',87),'auth',repeat('A',22))),180,false,'ko')$$,'owner opts in with interval');
select is((select feeding_interval_minutes from notification_preferences where user_id=auth.uid()),180,'interval persists');
select throws_ok($$select enable_feeding_push(jsonb_build_object('endpoint','https://127.0.0.1/private','keys',jsonb_build_object('p256dh',repeat('B',87),'auth',repeat('A',22))),240,false,'ko')$$,'23514',null,'private/internal endpoints are rejected');
select is((select feeding_interval_minutes from notification_preferences where user_id=auth.uid()),180,'invalid endpoint rolls back preference changes');
select throws_ok($$select claim_feeding_push(repeat('a',64))$$,'42501',null,'browser cannot claim jobs');
select throws_ok($$select * from feeding_push_config$$,'42501',null,'browser cannot read worker secret reference');
select throws_ok($$insert into web_push_subscriptions(user_id,endpoint,p256dh,auth_key,locale) values(auth.uid(),'https://fcm.googleapis.com/fcm/send/direct',repeat('B',87),repeat('A',22),'ko')$$,'42501',null,'direct subscription writes are denied');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from web_push_subscriptions),0,'another account cannot read subscription keys');
reset role;
update web_push_subscriptions set created_at=now()-interval '1 day' where user_id='e1000000-0000-4000-8000-000000000001';
insert into care_records(id,child_id,kind,started_at,ended_at,record_timezone,created_by,updated_by) values('e4000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','formula',now()-interval '181 minutes',null,'UTC','e1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001');
select is((select count(*)::int from feeding_push_candidates()),1,'bottle without optional duration still schedules from start');
select throws_ok($$select claim_feeding_push('wrong-token')$$,'42501','forbidden','worker token is verified even for service access');
create temporary table first_claim as select * from claim_feeding_push(repeat('a',64));
select is((select count(*)::int from first_claim),1,'due reminder is leased once');
select ok((select validate_feeding_push(id,lease_token) from first_claim),'leased reminder remains valid');
select is((select count(*)::int from claim_feeding_push(repeat('a',64))),0,'parallel worker cannot lease the same reminder');
insert into care_records(id,child_id,kind,started_at,record_timezone,created_by,updated_by) values('e4000000-0000-4000-8000-000000000002','e3000000-0000-4000-8000-000000000001','solids',now()-interval '180 minutes','UTC','e1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001');
select ok(not (select validate_feeding_push(id,lease_token) from first_claim),'a newer solids record invalidates the older bottle reminder');
select finish_feeding_push(id,lease_token,'cancelled') from first_claim;
create temporary table second_claim as select * from claim_feeding_push(repeat('a',64));
select is((select count(*)::int from second_claim),1,'latest solids meal gets one reminder');
select finish_feeding_push(id,lease_token,'sent') from second_claim;
select is((select count(*)::int from claim_feeding_push(repeat('a',64))),0,'successful reminder never repeats');
insert into care_records(id,child_id,kind,started_at,ended_at,record_timezone,created_by,updated_by) values('e4000000-0000-4000-8000-000000000003','e3000000-0000-4000-8000-000000000001','breast',now()-interval '179 minutes',now()-interval '170 minutes','UTC','e1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001');
select is((select count(*)::int from feeding_push_candidates()),0,'future reminder is not delivered early');
update care_records set started_at=now()-interval '180 minutes'+interval '1 second' where id='e4000000-0000-4000-8000-000000000002';
update care_records set started_at=now()-interval '179 minutes' where id='e4000000-0000-4000-8000-000000000001';
-- Move all meals outside the delivery grace period.
update care_records set started_at=started_at-interval '3 days',ended_at=case when ended_at is not null then ended_at-interval '3 days' end where child_id='e3000000-0000-4000-8000-000000000001';
select is((select count(*)::int from feeding_push_candidates()),0,'old records do not generate a backlog of reminders');
update care_records set started_at=now()-interval '180 minutes',ended_at=now()-interval '170 minutes' where id='e4000000-0000-4000-8000-000000000003';
select is((select count(*)::int from feeding_push_candidates()),1,'completed breast feeding schedules from start');
update notification_preferences set quiet_start=(now() at time zone 'UTC'-interval '30 minutes')::time,quiet_end=(now() at time zone 'UTC'+interval '30 minutes')::time where user_id='e1000000-0000-4000-8000-000000000001';
select is((select count(*)::int from feeding_push_candidates()),0,'quiet hours suppress delivery');
update notification_preferences set quiet_start='00:00',quiet_end='00:00',feeding_enabled=false;
select is((select count(*)::int from feeding_push_candidates()),0,'opt-out suppresses delivery');
update notification_preferences set feeding_enabled=true;
insert into data_operation_jobs(user_id) values('e1000000-0000-4000-8000-000000000001');
select is((select count(*)::int from feeding_push_candidates()),0,'accounts pending deletion receive no reminders');
delete from data_operation_jobs where user_id='e1000000-0000-4000-8000-000000000001';
create temporary table rescheduled as select * from claim_feeding_push(repeat('a',64));
update notification_preferences set feeding_interval_minutes=181;
select ok(not (select validate_feeding_push(id,lease_token) from rescheduled),'changing interval invalidates a queued reminder');
select finish_feeding_push(id,lease_token,'cancelled') from rescheduled;
update care_records set started_at=now()-interval '182 minutes' where id='e4000000-0000-4000-8000-000000000003';
create temporary table third_claim as select * from claim_feeding_push(repeat('a',64));
select is((select count(*)::int from third_claim),1,'a changed interval reschedules an unsent reminder at its new due time');
select finish_feeding_push(id,gen_random_uuid(),'sent') from third_claim;
select is((select status from feeding_push_deliveries where id=(select id from third_claim)),'sending','stale lease token cannot finish a job');
select finish_feeding_push(id,lease_token,'gone') from third_claim;
select is((select count(*)::int from web_push_subscriptions),0,'expired push endpoints and their jobs are removed');
insert into family_members(family_id,user_id,role) values('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002','viewer');
insert into child_access(child_id,family_id,user_id,role) values('e3000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002','viewer');
insert into notification_preferences(user_id,feeding_enabled,quiet_start,quiet_end,feeding_interval_minutes) values('e1000000-0000-4000-8000-000000000002',true,'00:00','00:00',180);
insert into web_push_subscriptions(user_id,endpoint,p256dh,auth_key,locale,created_at) values('e1000000-0000-4000-8000-000000000002','https://web.push.apple.com/fixture',repeat('B',87),repeat('A',22),'en',now()-interval '1 day');
select is((select count(*)::int from feeding_push_candidates()),1,'a viewer with child access may receive meal reminders');
delete from child_access where user_id='e1000000-0000-4000-8000-000000000002';
select is((select count(*)::int from feeding_push_candidates()),0,'revoking child access prevents subsequent push delivery');
select ok(not has_function_privilege('anon','public.enable_feeding_push(jsonb,integer,boolean,text)','execute'),'anonymous cannot opt in for another user');
select * from finish();
rollback;
